CREATE   VIEW [FO].[vwIntercompany_Recon_Multi_Account] AS

WITH CTE AS (
	SELECT 
		 LT.SUBLEDGERVOUCHER
		,COUNT(DISTINCT CT.ACCOUNTNUM) AS Countt
	FROM [synapse_fo].[LEDGERTRANS_RICS] LT
		LEFT JOIN [synapse_fo].[CUSTTRANS_RICS] CT
			ON CT.VOUCHER = LT.SUBLEDGERVOUCHER
	WHERE LT.MAINACCOUNT = 000000
	--AND SUBLEDGERVOUCHER = 'RCS000000'
	GROUP BY LT.SUBLEDGERVOUCHER
	HAVING COUNT(DISTINCT CT.ACCOUNTNUM) > 1
	)

SELECT 
	 LT.SUBLEDGERVOUCHER
	,CTB.AccountNum AS 'Cust. Account No'
	,CTB.Name As 'Cust. Name'
FROM [synapse_fo].[LEDGERTRANS_RICS] LT
INNER JOIN CTE
	ON CTE.SUBLEDGERVOUCHER = LT.SUBLEDGERVOUCHER
LEFT JOIN [synapse_fo].[CUSTTRANS_RICS] CT
	ON CT.VOUCHER = LT.SUBLEDGERVOUCHER
LEFT JOIN FO.vwCustTable CTB
	ON CTB.AccountNum = CT.ACCOUNTNUM
WHERE LT.MAINACCOUNT = 000000
